                if (offsetValue > 18446744073709551613) // a read rejects out-of-range (SPEC §5) — not latched
                {
                    return false;
                }
                value.ClampedCeiling = offsetValue + 1;
            }
            {
                ulong rawValue = 0;
                if (!batch.SerializeBits64(ref rawValue, 64))
                {
                    return false;
                }
                value.FloorDef = (long)rawValue;
            }
            if (!batch.SerializeBits64(ref value.CeilingDef, 64))
            {
                return false;
            }
            return true;
        }
    }

}
